/**
 * Benchmark Module
 * Handles performance benchmarking and device classification
 */

/**
 * Run benchmark iterations on face detection
 * @param {FaceLandmarker} faceLandmarker - Initialized face landmarker instance
 * @param {HTMLImageElement|HTMLCanvasElement|ImageData} image - Image to process
 * @param {number} iterations - Number of iterations to run
 * @returns {Promise<Object>} Benchmark results with statistics
 */
export async function runBenchmark(faceLandmarker, image, iterations = 10) {
  if (!faceLandmarker) {
    throw new Error('Face landmarker is not initialized');
  }

  if (!image) {
    throw new Error('Image is required for benchmarking');
  }

  const executionTimes = [];
  let totalTime = 0;

  // Warm-up run (not counted in results)
  // This helps stabilize performance by loading any lazy resources
  try {
    faceLandmarker.detect(image);
  } catch (error) {
    console.warn('Warm-up run failed:', error);
  }

  // Run benchmark iterations
  for (let i = 0; i < iterations; i++) {
    const startTime = performance.now();
    
    try {
      // Perform face detection with landmarks, iris, and blendshapes
      const results = faceLandmarker.detect(image);
      
      const endTime = performance.now();
      const executionTime = endTime - startTime;
      
      executionTimes.push(executionTime);
      totalTime += executionTime;

      // Validate that we got results
      if (!results || !results.faceLandmarks || results.faceLandmarks.length === 0) {
        console.warn(`Iteration ${i + 1}: No face detected in image`);
      }
    } catch (error) {
      console.error(`Iteration ${i + 1} failed:`, error);
      // Record a failed iteration as a very high time
      executionTimes.push(Number.MAX_SAFE_INTEGER);
    }
  }

  // Calculate statistics
  const stats = calculateStatistics(executionTimes);

  return {
    executionTimes: executionTimes,
    totalTime: totalTime,
    meanTime: stats.mean,
    medianTime: stats.median,
    minTime: stats.min,
    maxTime: stats.max,
    standardDeviation: stats.stdDev,
    iterations: iterations
  };
}

/**
 * Calculate statistical metrics from execution times
 * @param {number[]} times - Array of execution times
 * @returns {Object} Statistical metrics
 */
function calculateStatistics(times) {
  if (!times || times.length === 0) {
    return {
      mean: 0,
      median: 0,
      min: 0,
      max: 0,
      stdDev: 0
    };
  }

  // Mean
  const mean = times.reduce((sum, time) => sum + time, 0) / times.length;

  // Median
  const sortedTimes = [...times].sort((a, b) => a - b);
  const mid = Math.floor(sortedTimes.length / 2);
  const median = sortedTimes.length % 2 === 0
    ? (sortedTimes[mid - 1] + sortedTimes[mid]) / 2
    : sortedTimes[mid];

  // Min and Max
  const min = Math.min(...times);
  const max = Math.max(...times);

  // Standard Deviation
  const squaredDiffs = times.map(time => Math.pow(time - mean, 2));
  const variance = squaredDiffs.reduce((sum, diff) => sum + diff, 0) / times.length;
  const stdDev = Math.sqrt(variance);

  return {
    mean: mean,
    median: median,
    min: min,
    max: max,
    stdDev: stdDev
  };
}

/**
 * Classify device performance based on mean execution time
 * @param {number} meanTime - Mean execution time in milliseconds
 * @returns {Object} Device classification with details
 */
export function classifyDevice(meanTime) {
  // Classification thresholds (in milliseconds)
  const THRESHOLDS = {
    HIGH_END: 100,      // < 100ms = high-end
    MEDIUM_END: 200     // 100-200ms = medium-end, > 200ms = low-end
  };

  let category;
  let recommendation;
  let description;

  if (meanTime < THRESHOLDS.HIGH_END) {
    category = 'high-end';
    recommendation = 'recommended';
    description = 'Excellent performance. Device can handle real-time face detection smoothly.';
  } else if (meanTime < THRESHOLDS.MEDIUM_END) {
    category = 'medium-end';
    recommendation = 'acceptable';
    description = 'Good performance. Device can handle face detection adequately with possible minor delays.';
  } else {
    category = 'low-end';
    recommendation = 'not recommended';
    description = 'Limited performance. Device may struggle with real-time face detection and experience significant delays.';
  }

  return {
    category: category,
    recommendation: recommendation,
    description: description,
    meanExecutionTime: meanTime,
    thresholds: THRESHOLDS,
    performanceScore: calculatePerformanceScore(meanTime, THRESHOLDS)
  };
}

/**
 * Calculate a normalized performance score (0-100)
 * @param {number} meanTime - Mean execution time in milliseconds
 * @param {Object} thresholds - Performance thresholds
 * @returns {number} Performance score (0-100)
 */
function calculatePerformanceScore(meanTime, thresholds) {
  // Score calculation:
  // - 0ms = 100 points
  // - HIGH_END threshold = 80 points
  // - MEDIUM_END threshold = 50 points
  // - 2x MEDIUM_END threshold = 0 points

  if (meanTime <= 0) {
    return 100;
  }

  if (meanTime < thresholds.HIGH_END) {
    // Linear interpolation between 80-100
    const ratio = meanTime / thresholds.HIGH_END;
    return 100 - (ratio * 20);
  } else if (meanTime < thresholds.MEDIUM_END) {
    // Linear interpolation between 50-80
    const range = thresholds.MEDIUM_END - thresholds.HIGH_END;
    const position = meanTime - thresholds.HIGH_END;
    const ratio = position / range;
    return 80 - (ratio * 30);
  } else {
    // Linear interpolation between 0-50
    const maxTime = thresholds.MEDIUM_END * 2;
    if (meanTime >= maxTime) {
      return 0;
    }
    const range = maxTime - thresholds.MEDIUM_END;
    const position = meanTime - thresholds.MEDIUM_END;
    const ratio = position / range;
    return 50 - (ratio * 50);
  }
}

/**
 * Format benchmark results for display
 * @param {Object} results - Benchmark results
 * @returns {string} Formatted results string
 */
export function formatBenchmarkResults(results) {
  const lines = [];
  
  lines.push('=== Device Benchmark Results ===\n');
  
  // Device Information
  lines.push('Device Information:');
  lines.push(`  Type: ${results.device.device.type}`);
  lines.push(`  OS: ${results.device.os.name} ${results.device.os.version}`);
  lines.push(`  Browser: ${results.device.browser.name} ${results.device.browser.version}`);
  lines.push(`  CPU Cores: ${results.device.device.cpuCores}`);
  lines.push(`  GPU: ${results.device.gpu.renderer}\n`);
  
  // Setup Timing
  lines.push('Setup Performance:');
  lines.push(`  Download Time: ${results.setup.downloadTime.toFixed(2)}ms`);
  lines.push(`  Initialization Time: ${results.setup.initTime.toFixed(2)}ms`);
  lines.push(`  Total Setup Time: ${results.setup.totalSetupTime.toFixed(2)}ms\n`);
  
  // Benchmark Results
  lines.push('Benchmark Performance:');
  lines.push(`  Iterations: ${results.benchmark.iterations}`);
  lines.push(`  Mean Time: ${results.benchmark.meanTime.toFixed(2)}ms`);
  lines.push(`  Median Time: ${results.benchmark.medianTime.toFixed(2)}ms`);
  lines.push(`  Min Time: ${results.benchmark.minTime.toFixed(2)}ms`);
  lines.push(`  Max Time: ${results.benchmark.maxTime.toFixed(2)}ms`);
  lines.push(`  Std Deviation: ${results.benchmark.standardDeviation.toFixed(2)}ms`);
  lines.push(`  Total Time: ${results.benchmark.totalTime.toFixed(2)}ms\n`);
  
  // Classification
  lines.push('Device Classification:');
  lines.push(`  Category: ${results.classification.category.toUpperCase()}`);
  lines.push(`  Recommendation: ${results.classification.recommendation.toUpperCase()}`);
  lines.push(`  Performance Score: ${results.classification.performanceScore.toFixed(1)}/100`);
  lines.push(`  Description: ${results.classification.description}\n`);
  
  lines.push('================================');
  
  return lines.join('\n');
}

/**
 * Compare multiple benchmark results
 * @param {Object[]} resultsArray - Array of benchmark results
 * @returns {Object} Comparison analysis
 */
export function compareBenchmarks(resultsArray) {
  if (!resultsArray || resultsArray.length === 0) {
    throw new Error('No benchmark results provided for comparison');
  }

  const meanTimes = resultsArray.map(r => r.benchmark.meanTime);
  const categories = resultsArray.map(r => r.classification.category);

  return {
    count: resultsArray.length,
    meanTimes: {
      fastest: Math.min(...meanTimes),
      slowest: Math.max(...meanTimes),
      average: meanTimes.reduce((sum, t) => sum + t, 0) / meanTimes.length
    },
    categories: {
      highEnd: categories.filter(c => c === 'high-end').length,
      mediumEnd: categories.filter(c => c === 'medium-end').length,
      lowEnd: categories.filter(c => c === 'low-end').length
    },
    results: resultsArray
  };
}

export default {
  runBenchmark,
  classifyDevice,
  formatBenchmarkResults,
  compareBenchmarks
};

